package com.newzkl.platform.base.biz.order.model.res;import lombok.AllArgsConstructor;import lombok.Builder;import lombok.Data;import lombok.NoArgsConstructor;import java.io.Serializable;import java.math.BigDecimal;import java.util.List;/** * 聊天响应 */@Data@Builder@AllArgsConstructor@NoArgsConstructorpublic class ChatResponse implements Serializable {    private static final long serialVersionUID = 1L;    /**     * 回复类型：TEXT / PRODUCT_RECOMMENDATION     */    private String type;    /**     * 回复内容     */    private String content;    /**     * 推荐商品列表     */    private List<ProductInfo> products;    /**     * 会话 ID     */    private String conversationId;    /**     * 是否结束     */    private Boolean finished;    /**     * 商品信息     */    @Data    @Builder    @AllArgsConstructor    @NoArgsConstructor    public static class ProductInfo implements Serializable {                private static final long serialVersionUID = 1L;                /** 商品 ID */        private String productId;                /** 商品名称 */        private String productName;                /** 规格 */        private String specification;                /** 材质 */        private String material;                /** 价格 */        private BigDecimal price;                /** 单位 */        private String unit;                /** 库存 */        private Integer stock;                /** 商品图片 URL */        private String imageUrl;                /** 详情页跳转链接 */        private String detailUrl;    }}